\text{Total amount to be paid back} & = \text{Borrowed amount} + (\text{Borrowed amount} \times 10\%) \\
& = 2000 + (2000 \times 0.10) \\
& = 2200 \\
\end{aligned}
\begin{aligned}
\text{Total amount paid by December} & = \text{Payment per month} \times \text{Number of months} \\
& = 165 \times 12 \\
& = 1980 \\
\end{aligned}
\begin{aligned}
\text{Remaining balance by December 31} & = \text{Total amount to be paid back} - \text{Total amount paid by December} \\
& = 2200 - 1980 \\
& = 220 \\
\end{aligned}
